"use client";

import * as React from "react";
import { Lock, LockOpen } from "lucide-react";

type DivProps = React.ComponentProps<"div">;
type DivBase = { [key in keyof DivProps as key extends "title" | "defaultValue" | "onChange" | "onReset" ? never : key]: DivProps[key] };

export type AllocationTone = "chart-1" | "chart-2" | "chart-3" | "chart-4" | "chart-5";

export type AllocationSegment = {
  id: string;
  label: string;
  /** Chart token for the segment face and legend dot. Defaults cycle through chart-1…5. */
  color?: AllocationTone;
  /** Smallest share the segment can be pushed down to, in percent. Defaults to 0. */
  min?: number;
  /** Start locked: the share stays put while its neighbours trade across it. */
  locked?: boolean;
};

export type AllocationSliderProps = DivBase & {
  segments: AllocationSegment[];
  /** Shares in percent, one per segment, adding up to 100. */
  value?: number[];
  defaultValue?: number[];
  /** Fires on every change, including each frame of a drag. */
  onValueChange?: (values: number[]) => void;
  /** Fires when a drag ends or a key, double-click or reset lands. */
  onValueCommit?: (values: number[]) => void;
  lockedIds?: string[];
  onLockedChange?: (id: string, locked: boolean) => void;
  /** Resolution of the shares, in percent. */
  step?: number;
  /** Amount the shares split; each legend entry shows its part of it. */
  total?: number;
  formatAmount?: (amount: number) => string;
  title?: React.ReactNode;
  showLegend?: boolean;
  showReset?: boolean;
  resetLabel?: React.ReactNode;
  onReset?: () => void;
  /** Double-clicking a divider splits what its two neighbours hold together evenly between them. */
  equalizeOnDoubleClick?: boolean;
  /** Called when someone starts to drag, presses a key, locks or resets. Hosts use it to stop tours or demos. */
  onInteractionStart?: (event: React.SyntheticEvent) => void;
  "aria-label"?: string;
};

type Pair = { left: number; right: number };
type Drag = { index: number; pointerId: number; start: number[]; left: number; width: number };

const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const DIGITS = Array.from({ length: 10 }, (_, index) => index);
const PALETTE: AllocationTone[] = ["chart-1", "chart-2", "chart-3", "chart-4", "chart-5"];
/** Rough glyph width at 12px and the horizontal padding of a segment label, used to pick how much of the label fits. */
const GLYPH = 7.2;
const LABEL_PAD = 20;

const roundTo = (value: number, step: number) => Math.round(Math.round(value / step) * step * 1e6) / 1e6;
const floorTo = (value: number, step: number) => Math.round(Math.floor(value / step + 1e-9) * step * 1e6) / 1e6;
const sumOf = (values: number[]) => values.reduce((total, value) => total + value, 0);
const same = (a: number[], b: number[]) => a.length === b.length && a.every((value, index) => value === b[index]);
const sameIds = (a: string[], b: string[]) => a.length === b.length && a.every((id) => b.includes(id));
const defaultFormat = (amount: number) => amount.toLocaleString("en-US", { maximumFractionDigits: 0 });

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(true);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

/** Odometer text: every digit sits in a column that rolls to its value; other characters stay put. */
function Roll({ text, reduced, className = "" }: { text: string; reduced: boolean; className?: string }) {
  const chars = Array.from(text);
  return (
    <span data-roll={text} className={`inline-flex items-end leading-none whitespace-nowrap tabular-nums ${className}`}>
      <span className="sr-only">{text}</span>
      {chars.map((character, index) => {
        const key = chars.length - index;
        if (!/\d/.test(character)) return <span key={key} aria-hidden="true" className="block h-[1em]">{character}</span>;
        return (
          <span key={key} aria-hidden="true" className="relative block h-[1em] w-[0.62em] overflow-hidden">
            <span
              data-digit={character}
              className="block"
              style={{ transform: `translateY(-${character}em)`, transition: reduced ? "none" : `transform 200ms ${EASE}` }}
            >
              {DIGITS.map((digit) => <span key={digit} className="block h-[1em] text-center">{digit}</span>)}
            </span>
          </span>
        );
      })}
    </span>
  );
}

export function AllocationSlider({
  segments,
  value,
  defaultValue,
  onValueChange,
  onValueCommit,
  lockedIds,
  onLockedChange,
  step = 1,
  total,
  formatAmount,
  title,
  showLegend = true,
  showReset = true,
  resetLabel = "Reset",
  onReset,
  equalizeOnDoubleClick = true,
  onInteractionStart,
  "aria-label": ariaLabel = "Allocation",
  className = "",
  ref,
  ...rest
}: AllocationSliderProps) {
  const reduced = useReducedMotion();
  const titleId = React.useId();
  const count = segments.length;
  const safeStep = Number.isFinite(step) && step > 0 ? step : 1;
  const [localLocked, setLocalLocked] = React.useState(() => segments.filter((segment) => segment.locked).map((segment) => segment.id));
  const locked = lockedIds ?? localLocked;
  const isLocked = (index: number) => { const segment = segments[index]; return !!segment && locked.includes(segment.id); };
  const minOf = (index: number) => Math.max(0, segments[index]?.min ?? 0);

  /** Clamp to each segment's floor, snap to the step and make the shares add up to 100 (the last unlocked segment absorbs the difference). */
  const normalize = (input: number[] | undefined): number[] => {
    if (!count) return [];
    const base = input && input.length === count ? input : Array.from({ length: count }, () => 100 / count);
    const next = base.map((raw, index) => Math.max(minOf(index), roundTo(Number.isFinite(raw) ? raw : 0, safeStep)));
    const diff = roundTo(100 - sumOf(next), safeStep);
    if (diff !== 0) {
      let target = count - 1;
      for (let index = count - 1; index >= 0; index--) if (!isLocked(index)) { target = index; break; }
      next[target] = Math.max(minOf(target), roundTo((next[target] ?? 0) + diff, safeStep));
    }
    return next;
  };

  const [localValue, setLocalValue] = React.useState(() => normalize(defaultValue ?? value));
  const values = normalize(value ?? localValue);
  const initial = React.useRef(null as { values: number[]; locked: string[] } | null);
  if (!initial.current) initial.current = { values, locked: [...locked] };
  const cum = values.map((_, index) => roundTo(sumOf(values.slice(0, index + 1)), safeStep));

  /** The two segments that trade when divider `index` moves: the nearest unlocked one on each side. Null means the divider is inert. */
  const receivers = (index: number): Pair | null => {
    if (index < 0 || index >= count - 1) return null;
    if (isLocked(index) && isLocked(index + 1)) return null;
    let left = index;
    while (left >= 0 && isLocked(left)) left--;
    let right = index + 1;
    while (right < count && isLocked(right)) right++;
    return left < 0 || right >= count ? null : { left, right };
  };
  const range = (start: number[], pair: Pair) => ({
    lo: -floorTo((start[pair.left] ?? 0) - minOf(pair.left), safeStep),
    hi: floorTo((start[pair.right] ?? 0) - minOf(pair.right), safeStep),
  });
  /** Move divider `index` by `delta` percent from `start`: the left receiver gains what the right receiver gives up, within both floors. */
  const shift = (start: number[], index: number, delta: number) => {
    const pair = receivers(index);
    if (!pair) return start;
    const { lo, hi } = range(start, pair);
    const amount = roundTo(Math.min(hi, Math.max(lo, delta)), safeStep);
    if (amount === 0) return start;
    const next = [...start];
    next[pair.left] = roundTo((next[pair.left] ?? 0) + amount, safeStep);
    next[pair.right] = roundTo((next[pair.right] ?? 0) - amount, safeStep);
    return next;
  };
  const summary = (list: number[]) => segments.map((segment, index) => `${segment.label} ${list[index] ?? 0}%`).join(", ");
  const commit = (next: number[]) => {
    if (same(next, values)) return;
    if (value === undefined) setLocalValue(next);
    onValueChange?.(next);
  };

  const trackRef = React.useRef(null as HTMLDivElement | null);
  const tipRef = React.useRef(null as HTMLDivElement | null);
  const segmentRefs = React.useRef([] as (HTMLDivElement | null)[]);
  const labelRefs = React.useRef([] as (HTMLSpanElement | null)[]);
  const dividerRefs = React.useRef([] as (HTMLDivElement | null)[]);
  const lockIconRefs = React.useRef({} as { [id: string]: HTMLSpanElement | null });
  const dragRef = React.useRef(null as Drag | null);
  const latest = React.useRef({ values, shift, commit });
  latest.current = { values, shift, commit };
  const previousLocked = React.useRef(locked);
  const announceTimer = React.useRef(0);
  const lastTip = React.useRef("");
  const pointerFocus = React.useRef(false);
  const [trackWidth, setTrackWidth] = React.useState(0);
  const [dragging, setDragging] = React.useState(-1);
  const [focused, setFocused] = React.useState(-1);
  const [announce, setAnnounce] = React.useState("");

  React.useLayoutEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    setTrackWidth(track.clientWidth);
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver((entries) => { for (const entry of entries) setTrackWidth(entry.contentRect.width); });
    observer.observe(track);
    return () => observer.disconnect();
  }, []);

  // Entrance, once: segments grow from the left one after another, then their labels and the dividers fade in.
  React.useLayoutEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const stagger = 170;
    segmentRefs.current.forEach((node, index) => {
      if (!node || typeof node.animate !== "function") return;
      node.animate([{ transform: "scaleX(0)" }, { transform: "scaleX(1)" }], { duration: 260, delay: index * stagger, easing: EASE, fill: "backwards" });
      labelRefs.current[index]?.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 200, delay: index * stagger + 140, easing: "ease-out", fill: "backwards" });
    });
    dividerRefs.current.forEach((node, index) => {
      node?.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 200, delay: (index + 1) * stagger + 80, easing: "ease-out", fill: "backwards" });
    });
  }, []);

  React.useLayoutEffect(() => {
    const before = previousLocked.current;
    previousLocked.current = locked;
    if (reduced) return;
    for (const segment of segments) {
      const was = before.includes(segment.id);
      const now = locked.includes(segment.id);
      if (was === now) continue;
      const icon = lockIconRefs.current[segment.id];
      if (!icon || typeof icon.animate !== "function") continue;
      icon.animate(now ? [{ transform: "translateY(-2px) scale(0.8)" }, { transform: "none" }] : [{ transform: "scale(0.8)" }, { transform: "none" }], { duration: 120, easing: EASE });
    }
  }, [locked.join("|")]);

  const finish = React.useCallback((drag: Drag) => {
    dragRef.current = null;
    setDragging(-1);
    const current = latest.current.values;
    setAnnounce(summary(current));
    onValueCommit?.(current);
    void drag;
  }, [onValueCommit, segments]);

  React.useEffect(() => {
    if (dragging < 0) return;
    const move = (event: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || event.pointerId !== drag.pointerId || drag.width <= 0) return;
      const percent = ((event.clientX - drag.left) / drag.width) * 100;
      const startCum = sumOf(drag.start.slice(0, drag.index + 1));
      latest.current.commit(latest.current.shift(drag.start, drag.index, percent - startCum));
    };
    const up = (event: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || event.pointerId !== drag.pointerId) return;
      finish(drag);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
    return () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
    };
  }, [dragging, finish]);

  React.useEffect(() => () => window.clearTimeout(announceTimer.current), []);

  const active = dragging >= 0 ? dragging : focused;
  const activePair = active >= 0 ? receivers(active) : null;

  // Keep the tooltip inside the track so it never pushes the page wider.
  React.useLayoutEffect(() => {
    const tip = tipRef.current;
    const track = trackRef.current;
    if (!tip || !track || active < 0) return;
    const width = track.clientWidth;
    const half = tip.offsetWidth / 2;
    const x = ((cum[active] ?? 0) / 100) * width;
    tip.style.left = `${Math.min(Math.max(half, width - half), Math.max(half, x))}px`;
  });

  const announceSoon = (text: string) => {
    window.clearTimeout(announceTimer.current);
    announceTimer.current = window.setTimeout(() => setAnnounce(text), 400);
  };

  const onHandlePointerDown = (index: number) => (event: React.PointerEvent) => {
    if (!receivers(index)) return;
    if (event.pointerType === "mouse" && event.button !== 0) return;
    const track = trackRef.current;
    if (!track) return;
    onInteractionStart?.(event);
    event.preventDefault();
    const handle = event.currentTarget;
    if (!(handle instanceof HTMLElement)) return;
    if (event.isTrusted) {
      pointerFocus.current = true;
      handle.focus({ preventScroll: true });
      pointerFocus.current = false;
    }
    try { handle.setPointerCapture(event.pointerId); } catch { /* synthetic pointers cannot be captured */ }
    const previous = dragRef.current;
    if (previous) finish(previous);
    const box = track.getBoundingClientRect();
    dragRef.current = { index, pointerId: event.pointerId, start: values, left: box.left, width: box.width };
    setDragging(index);
  };

  const onHandleKeyDown = (index: number) => (event: React.KeyboardEvent) => {
    const pair = receivers(index);
    if (!pair) return;
    const big = Math.max(safeStep, roundTo(10, safeStep));
    let delta = 0;
    if (event.key === "ArrowRight" || event.key === "ArrowUp") delta = event.shiftKey ? big : safeStep;
    else if (event.key === "ArrowLeft" || event.key === "ArrowDown") delta = event.shiftKey ? -big : -safeStep;
    else if (event.key === "PageUp") delta = big;
    else if (event.key === "PageDown") delta = -big;
    else if (event.key === "Home") delta = range(values, pair).lo;
    else if (event.key === "End") delta = range(values, pair).hi;
    else return;
    event.preventDefault();
    onInteractionStart?.(event);
    setFocused(index);
    const next = shift(values, index, delta);
    commit(next);
    announceSoon(summary(next));
    onValueCommit?.(next);
  };

  const onHandleDoubleClick = (index: number) => (event: React.MouseEvent) => {
    const pair = receivers(index);
    if (!equalizeOnDoubleClick || !pair) return;
    onInteractionStart?.(event);
    const together = (values[pair.left] ?? 0) + (values[pair.right] ?? 0);
    const left = Math.max(minOf(pair.left), Math.min(roundTo(together - minOf(pair.right), safeStep), roundTo(together / 2, safeStep)));
    const right = roundTo(together - left, safeStep);
    if (right < minOf(pair.right)) return;
    const next = [...values];
    next[pair.left] = left;
    next[pair.right] = right;
    commit(next);
    setAnnounce(summary(next));
    onValueCommit?.(next);
  };

  const toggleLock = (segment: AllocationSegment) => (event: React.MouseEvent) => {
    onInteractionStart?.(event);
    const now = !locked.includes(segment.id);
    const next = now ? [...locked, segment.id] : locked.filter((id) => id !== segment.id);
    if (lockedIds === undefined) setLocalLocked(next);
    onLockedChange?.(segment.id, now);
    setAnnounce(`${segment.label} ${now ? "locked" : "unlocked"}`);
  };

  const reset = (event: React.MouseEvent) => {
    const start = initial.current;
    if (!start) return;
    onInteractionStart?.(event);
    if (lockedIds === undefined) setLocalLocked(start.locked);
    for (const segment of segments) {
      const was = locked.includes(segment.id);
      const will = start.locked.includes(segment.id);
      if (was !== will) onLockedChange?.(segment.id, will);
    }
    commit(start.values);
    onValueCommit?.(start.values);
    onReset?.();
    setAnnounce(`Reset. ${summary(start.values)}`);
  };

  const modeOf = (index: number) => {
    const share = values[index] ?? 0;
    const px = (trackWidth * share) / 100;
    const percentChars = `${share}%`.length;
    const fullNeeds = ((segments[index]?.label.length ?? 0) + 1 + percentChars) * GLYPH + LABEL_PAD;
    const percentNeeds = percentChars * GLYPH + LABEL_PAD;
    return px >= fullNeeds ? "full" : px >= percentNeeds ? "percent" : "none";
  };

  const dirty = !!initial.current && (!same(values, initial.current.values) || !sameIds(locked, initial.current.locked));
  const format = formatAmount ?? defaultFormat;
  const settle = `left 400ms ${EASE}, width 400ms ${EASE}`;
  const tint = "opacity 200ms ease, background-color 200ms ease";
  const segmentTransition = reduced ? "none" : dragging >= 0 ? tint : `${settle}, ${tint}`;
  if (activePair) {
    const leftSegment = segments[activePair.left];
    const rightSegment = segments[activePair.right];
    lastTip.current = `${leftSegment?.label ?? ""} ${values[activePair.left] ?? 0} · ${rightSegment?.label ?? ""} ${values[activePair.right] ?? 0}`;
  }

  return (
    <div
      ref={ref}
      {...rest}
      data-slot="allocation-slider"
      data-values={values.join(",")}
      data-locked={locked.join(",")}
      data-dragging={dragging}
      role="group"
      aria-label={title ? undefined : ariaLabel}
      aria-labelledby={title ? titleId : undefined}
      className={`@container/allocation w-full ${className}`}
    >
      {(title || total !== undefined || showReset) && (
        <div className="mb-8 flex items-end justify-between gap-3">
          <div id={titleId} className="min-w-0 truncate text-sm font-semibold">{title}</div>
          <div className="flex items-baseline gap-3">
            {showReset && (
              <button
                type="button"
                data-reset
                disabled={!dirty}
                onClick={reset}
                className="rounded-sm text-xs font-medium text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40 motion-reduce:transition-none"
              >
                {resetLabel}
              </button>
            )}
            {total !== undefined && <Roll text={format(total)} reduced={reduced} className="text-lg font-semibold" />}
          </div>
        </div>
      )}
      <div ref={trackRef} data-track className="relative h-11 w-full select-none rounded-xl bg-muted ring-1 ring-border/60">
        <div className="absolute inset-0 overflow-hidden rounded-xl">
          {segments.map((segment, index) => {
            const tone = segment.color ?? PALETTE[index % PALETTE.length] ?? "chart-1";
            const lockedHere = locked.includes(segment.id);
            const state = activePair ? (index === activePair.left || index === activePair.right ? "emphasis" : "recede") : "rest";
            const mode = modeOf(index);
            const share = values[index] ?? 0;
            const left = index === 0 ? 0 : cum[index - 1] ?? 0;
            const face = `color-mix(in oklch, var(--color-${tone}) ${state === "emphasis" ? 38 : 24}%, transparent)`;
            const hatch = `repeating-linear-gradient(135deg, transparent 0 5px, color-mix(in oklch, var(--color-${tone}) 28%, transparent) 5px 7px)`;
            return (
              <div
                key={segment.id}
                ref={(node) => { segmentRefs.current[index] = node; }}
                data-segment={segment.id}
                data-value={share}
                data-locked={lockedHere}
                data-state={state}
                data-mode={mode}
                title={mode === "none" ? `${segment.label} ${share}%` : undefined}
                style={{ left: `${left}%`, width: `${share}%`, backgroundColor: face, backgroundImage: lockedHere ? hatch : undefined, opacity: state === "recede" ? 0.75 : 1, transition: segmentTransition }}
                className="absolute inset-y-0 origin-left"
              >
                <span aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 h-px bg-background/60 dark:bg-foreground/15" />
                {mode !== "none" && (
                  <span ref={(node) => { labelRefs.current[index] = node; }} className="absolute inset-0 flex items-center overflow-hidden px-2.5 text-[12px] text-foreground">
                    <span className="inline-flex min-w-0 items-end gap-1 leading-none whitespace-nowrap">
                      {mode === "full" && <span data-label className="block h-[1em] truncate font-medium">{segment.label}</span>}
                      <Roll text={`${share}%`} reduced={reduced} className={mode === "full" ? "" : "font-medium"} />
                    </span>
                  </span>
                )}
              </div>
            );
          })}
        </div>
        {segments.slice(0, -1).map((segment, index) => {
          const pair = receivers(index);
          const disabled = !pair;
          const leftSegment = pair ? segments[pair.left] : segment;
          const rightSegment = pair ? segments[pair.right] : segments[index + 1];
          const leftValue = values[pair ? pair.left : index] ?? 0;
          const rightValue = values[pair ? pair.right : index + 1] ?? 0;
          const bounds = pair ? range(values, pair) : { lo: 0, hi: 0 };
          const grabbing = dragging === index;
          return (
            <div
              key={`divider-${segment.id}`}
              ref={(node) => { dividerRefs.current[index] = node; }}
              data-divider={index}
              data-grabbing={grabbing}
              data-disabled={disabled}
              role="slider"
              tabIndex={disabled ? -1 : 0}
              aria-disabled={disabled || undefined}
              aria-orientation="horizontal"
              aria-label={`${leftSegment?.label ?? ""} and ${rightSegment?.label ?? ""}`}
              aria-valuemin={roundTo(leftValue + bounds.lo, safeStep)}
              aria-valuemax={roundTo(leftValue + bounds.hi, safeStep)}
              aria-valuenow={leftValue}
              aria-valuetext={`${leftSegment?.label ?? ""} ${leftValue} percent, ${rightSegment?.label ?? ""} ${rightValue} percent`}
              style={{ left: `${cum[index] ?? 0}%`, transition: reduced || dragging >= 0 ? "none" : `left 400ms ${EASE}` }}
              onPointerDown={onHandlePointerDown(index)}
              onKeyDown={onHandleKeyDown(index)}
              onDoubleClick={onHandleDoubleClick(index)}
              onFocus={() => { if (!pointerFocus.current) setFocused(index); }}
              onBlur={() => setFocused((current) => (current === index ? -1 : current))}
              className={`group absolute top-1/2 z-10 flex h-[calc(100%+8px)] w-4 -translate-x-1/2 -translate-y-1/2 items-center justify-center outline-none ${disabled ? "cursor-not-allowed" : "cursor-ew-resize touch-none"}`}
            >
              <span
                data-handle
                className={`block h-full rounded-full bg-background ring-1 ring-border transition-[width,transform,box-shadow,background-color] duration-150 ease-out group-focus-visible:ring-2 group-focus-visible:ring-ring motion-reduce:transition-none ${disabled ? "w-1 opacity-50 dark:bg-foreground/40" : grabbing ? "w-1.5 -translate-y-0.5 shadow-lg shadow-foreground/20 dark:bg-foreground" : "w-1 shadow-sm group-hover:w-1.5 group-hover:shadow-md dark:bg-foreground/70 dark:group-hover:bg-foreground/90"}`}
              />
            </div>
          );
        })}
        <div
          ref={tipRef}
          data-tooltip
          data-open={active >= 0 && !!activePair}
          aria-hidden="true"
          className="pointer-events-none absolute bottom-[calc(100%+6px)] z-20 -translate-x-1/2 rounded-md bg-foreground px-2 py-1 text-[11px] font-medium whitespace-nowrap text-background shadow-md transition-[opacity,translate] duration-150 ease-out data-[open=false]:translate-y-1 data-[open=false]:opacity-0 motion-reduce:transition-none"
        >
          <span className="tabular-nums">{lastTip.current}</span>
          <span className="absolute -bottom-1 left-1/2 size-2 -translate-x-1/2 rotate-45 bg-foreground" />
        </div>
      </div>
      {showLegend && (
        <ul data-legend className="mt-4 grid grid-cols-2 gap-x-3 gap-y-2 @min-[480px]/allocation:grid-cols-4">
          {segments.map((segment, index) => {
            const tone = segment.color ?? PALETTE[index % PALETTE.length] ?? "chart-1";
            const lockedHere = locked.includes(segment.id);
            const share = values[index] ?? 0;
            const amount = total !== undefined ? format((total * share) / 100) : `${share}%`;
            return (
              <li
                key={segment.id}
                data-legend-item={segment.id}
                data-locked={lockedHere}
                className={`flex items-center gap-2 rounded-lg py-1.5 pr-1 pl-2 ring-1 transition-colors motion-reduce:transition-none ${lockedHere ? "bg-muted/70 ring-border/70" : "ring-transparent"}`}
              >
                <span aria-hidden="true" className="size-2 shrink-0 rounded-full" style={{ backgroundColor: `var(--color-${tone})` }} />
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-[11px] leading-4 text-muted-foreground">{segment.label}</span>
                  <span data-amount={total !== undefined ? (total * share) / 100 : share} className="block text-[13px] font-semibold">
                    <Roll text={amount} reduced={reduced} />
                  </span>
                </span>
                <button
                  type="button"
                  data-lock={segment.id}
                  aria-pressed={lockedHere}
                  aria-label={`${lockedHere ? "Unlock" : "Lock"} ${segment.label}`}
                  onClick={toggleLock(segment)}
                  className={`flex size-7 shrink-0 items-center justify-center rounded-md outline-none transition-colors hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring motion-reduce:transition-none ${lockedHere ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                >
                  <span ref={(node) => { lockIconRefs.current[segment.id] = node; }} className="flex">
                    {lockedHere ? <Lock aria-hidden="true" className="size-3.5" /> : <LockOpen aria-hidden="true" className="size-3.5" />}
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      )}
      <p role="status" aria-live="polite" aria-atomic="true" className="sr-only">{announce}</p>
    </div>
  );
}

